72	  private async performCheck(teammateId: string, checkFn: () => Promise<boolean>): Promise<void> {
73	    const check = this.checks.get(teammateId);
74	    if (!check) return;
75	
76	    const startTime = Date.now();
77	    const previousStatus = check.status;
78	
79	    try {
80	      const timeoutPromise = new Promise<boolean>((_, reject) => {
81	        setTimeout(() => reject(new Error('Health check timeout')), this.config.timeoutMs);
82	      });
83	
84	      const healthy = await Promise.race([checkFn(), timeoutPromise]);
85	      const latency = Date.now() - startTime;
86	
87	      check.lastCheck = new Date();
88	      check.latencyMs = latency;
89	
90	      if (healthy) {
91	        check.consecutiveSuccesses++;
92	        check.consecutiveFailures = 0;
93	        check.lastHealthy = new Date();
94	        check.error = undefined;
95	
96	        if (check.consecutiveSuccesses >= this.config.healthyThreshold) {
97	          check.status = 'healthy';
98	        } else if (check.status === 'unhealthy') {
99	          check.status = 'degraded';
100	        }
101	      } else {
102	        throw new Error('Health check returned false');
103	      }
104	    } catch (error) {
105	      check.lastCheck = new Date();
106	      check.consecutiveFailures++;
107	      check.consecutiveSuccesses = 0;
108	      check.error = error instanceof Error ? error.message : String(error);
109	
110	      if (check.consecutiveFailures >= this.config.unhealthyThreshold) {
111	        check.status = 'unhealthy';
112	      } else {
113	        check.status = 'degraded';
114	      }
115	    }
116	
117	    if (check.status !== previousStatus && this.onStatusChange) {
118	      this.onStatusChange(check);
119	    }
120	  }
